TfRS232Main::TfRS232Main()
    : CommTester(0), MemoLog(0), cbBaudRate(0), cbByteSize(0), cbStopBit(0), cbParity(0), cbDevice(0),
      edReadIntervalTimeout(0), bCommConnect(false), iHasCE(0)                 // VCL zero-fills a new TForm
{
    //AI(W906-GB-P1) 20260926: RS232.dfm:16-46 -- CommTester is the form's only .dfm component (owned here).  Only
    //  the properties vclcompat TComm carries are applied; Outx_CtsFlow=False, Outx_DsrFlow=False,
    //  DtrControl=DtrEnable, DsrSensitivity=False, TxContinueOnXoff=True, ReplaceWhenParityError=False,
    //  IgnoreNullChar=False, RtsControl=RtsEnable, XonLimit=500, XoffLimit=500, XonChar=#17, XoffChar=#19,
    //  ReplacedChar=#0 and the Read/WriteTotalTimeout* (all 0) have no vclcompat member (Comm.h:37-41).
    //  LoadSetupData() (golden Main.cpp:615) overwrites CommName/BaudRate/ByteSize/StopBits/Parity/
    //  ReadIntervalTimeout from D:\RS232Standard\System\Setup.ini before OpenTesterComm() (Main.cpp:616).
    CommTester=new TComm(0);
    CommTester->CommName            ="COM13";
    CommTester->BaudRate            =9600;
    CommTester->ParityCheck         =false;
    CommTester->Outx_XonXoffFlow    =true;
    CommTester->Inx_XonXoffFlow     =true;
    CommTester->ByteSize            =Spcomm::_7;
    CommTester->Parity              =Spcomm::Even;
    CommTester->StopBits            =Spcomm::_1;
    CommTester->ReadIntervalTimeout =1;
    //AI(W906-GB-P1) 20260926: .dfm `OnReceiveData = CommTesterReceiveData`.  vclcompat fires it on the COM reader
    //  thread, so only queue the bytes; TSerialPoll::DrainRx() calls CommTesterReceiveData on the TesterComm thread.
    CommTester->OnReceiveData=[](TObject*, void* b, Word n){ if (SerialPoll) SerialPoll->QueueRx(TSerialPoll::kRxAuxTester, b, n); };

    if(SerialPoll                        &&
       SerialPoll->MemoLog               &&
       SerialPoll->cbBaudRate            &&
       SerialPoll->cbByteSize            &&
       SerialPoll->cbStopBit             &&
       SerialPoll->cbParity              &&
       SerialPoll->cbDevice              &&
       SerialPoll->edReadIntervalTimeout)
    {
        MemoLog     =SerialPoll->MemoLog;
        cbBaudRate  =SerialPoll->cbBaudRate;
        cbByteSize  =SerialPoll->cbByteSize;
        cbStopBit   =SerialPoll->cbStopBit ;
        cbParity    =SerialPoll->cbParity  ;
        cbDevice    =SerialPoll->cbDevice  ;
        edReadIntervalTimeout=SerialPoll->edReadIntervalTimeout;
    }
    else
    {
        //AI(W906-GB-P1) 20260926: golden dereferences SerialPoll unconditionally (it is always created first,
        //  H9046_32GPIB.cpp:19-22).  In-process a NULL there would take the Handler down, so if the owner builds
        //  this form before SerialPoll's widgets exist it gets private stand-ins (not shown on SerialPoll's RS232
        //  tab) instead of a crash.  The destructor frees only these.
        MemoLog     =new TMemo;
        cbBaudRate  =new TComboBox;
        cbByteSize  =new TComboBox;
        cbStopBit   =new TComboBox;
        cbParity    =new TComboBox;
        cbDevice    =new TComboBox;
        edReadIntervalTimeout=new TEdit;
        RsFallbackOwners().insert(this);
    }
}

TfRS232Main::~TfRS232Main()
{
    //AI(W906-GB-P1) 20260926: VCL frees the owned CommTester with the form (SPComm's destructor stops its threads);
    //  vclcompat ~TComm() calls StopComm(), which joins the reader thread, so no OnReceiveData fires after this.
    delete CommTester;
    CommTester=0;

    if(RsFallbackOwners().erase(this)>0)
    {
        delete MemoLog;
        delete cbBaudRate;
        delete cbByteSize;
        delete cbStopBit;
        delete cbParity;
        delete cbDevice;
        delete edReadIntervalTimeout;
    }
    // otherwise they are SerialPoll's widgets (golden ctor aliases them) and SerialPoll frees them
    MemoLog=0;
    cbBaudRate=0;
    cbByteSize=0;
    cbStopBit=0;
    cbParity=0;
    cbDevice=0;
    edReadIntervalTimeout=0;
}

bool TfRS232Main::SaveSetupData()                                               //JerryYang 20160630 RS232加入GPIB
{
    TIniFile* IniFile=new TIniFile("D:\\RS232Standard\\System\\Setup.ini");

    IniFile->WriteString( "COMPort", "CommName", CommTester->CommName);
    IniFile->WriteInteger("COMPort", "BaudRate", CommTester->BaudRate);
    IniFile->WriteInteger("COMPort", "ByteSize", CommTester->ByteSize);
    IniFile->WriteInteger("COMPort", "StopBits", CommTester->StopBits);
    IniFile->WriteInteger("COMPort", "Parity"  , CommTester->Parity  );
    IniFile->WriteString("Detail Settng", "ReadIntervalTimeout", edReadIntervalTimeout->Text);   //wei 20150212  add
    delete IniFile;
    return true;
}

void TfRS232Main::SetFormToData()
{
    CommTester->CommName=cbDevice->Text;
    CommTester->BaudRate=atoi(cbBaudRate->Text.c_str());

    if(     cbByteSize->ItemIndex==0)   CommTester->ByteSize    =Spcomm::_5;
    else if(cbByteSize->ItemIndex==1)   CommTester->ByteSize    =Spcomm::_6;
    else if(cbByteSize->ItemIndex==2)   CommTester->ByteSize    =Spcomm::_7;
    else if(cbByteSize->ItemIndex==3)   CommTester->ByteSize    =Spcomm::_8;

    if(     cbStopBit->ItemIndex==0)    CommTester->StopBits    =Spcomm::_1;
    else if(cbStopBit->ItemIndex==1)    CommTester->StopBits    =Spcomm::_1_5;
    else if(cbStopBit->ItemIndex==2)    CommTester->StopBits    =Spcomm::_2;

    if(     cbParity->ItemIndex==0)     CommTester->Parity      =Spcomm::None;
    else if(cbParity->ItemIndex==1)     CommTester->Parity      =Spcomm::Odd;
    else if(cbParity->ItemIndex==2)     CommTester->Parity      =Spcomm::Even;
    else if(cbParity->ItemIndex==3)     CommTester->Parity      =Spcomm::Mark;
    else if(cbParity->ItemIndex==4)     CommTester->Parity      =Spcomm::Space;

    SaveSetupData();
}

void TfRS232Main::InitDataToMainForm()
{
    cbDevice->Text  =CommTester->CommName;
    cbBaudRate->Text=IntToStr(CommTester->BaudRate);

    if(     CommTester->ByteSize==Spcomm::_5)   cbByteSize->ItemIndex=0;
    else if(CommTester->ByteSize==Spcomm::_6)   cbByteSize->ItemIndex=1;
    else if(CommTester->ByteSize==Spcomm::_7)   cbByteSize->ItemIndex=2;
    else if(CommTester->ByteSize==Spcomm::_8)   cbByteSize->ItemIndex=3;

    if(     CommTester->StopBits==Spcomm::_1)   cbStopBit->ItemIndex=0;
    else if(CommTester->StopBits==Spcomm::_1_5) cbStopBit->ItemIndex=1;
    else if(CommTester->StopBits==Spcomm::_2)   cbStopBit->ItemIndex=2;

    if(     CommTester->Parity==Spcomm::None)   cbParity->ItemIndex=0;
    else if(CommTester->Parity==Spcomm::Odd)    cbParity->ItemIndex=1;
    else if(CommTester->Parity==Spcomm::Even)   cbParity->ItemIndex=2;
    else if(CommTester->Parity==Spcomm::Mark)   cbParity->ItemIndex=3;
    else if(CommTester->Parity==Spcomm::Space)  cbParity->ItemIndex=4;

    edReadIntervalTimeout->Text=CommTester->ReadIntervalTimeout;                //wei 20150212  add
}

void TComm::ApplyCommState_()
{
#if defined(_WIN32)
    if (pImpl_->hFile == INVALID_HANDLE_VALUE)
        return;

    DCB dcb;
    ::memset(&dcb, 0, sizeof(dcb));
    dcb.DCBlength = sizeof(dcb);
    if (!::GetCommState(pImpl_->hFile, &dcb))
        return;

    dcb.BaudRate = BaudRate;

    // ByteSize enum (_5.._8) maps to 5..8 data bits.
    switch (ByteSize) {
        case _5: dcb.ByteSize = 5; break;
        case _6: dcb.ByteSize = 6; break;
        case _7: dcb.ByteSize = 7; break;
        case _8: default: dcb.ByteSize = 8; break;
    }

    // Parity enum -> Win32 *PARITY constants.
    switch (Parity) {
        case Odd:   dcb.Parity = ODDPARITY;   break;
        case Even:  dcb.Parity = EVENPARITY;  break;
        case Mark:  dcb.Parity = MARKPARITY;  break;
        case Space: dcb.Parity = SPACEPARITY; break;
        case None:  default: dcb.Parity = NOPARITY; break;
    }
    dcb.fParity = ParityCheck ? TRUE : FALSE;

    // StopBits enum (_1,_1_5,_2) -> Win32 stop-bit constants.
    switch (StopBits) {
        case _1_5: dcb.StopBits = ONE5STOPBITS; break;
        case _2:   dcb.StopBits = TWOSTOPBITS;  break;
        case _1:   default: dcb.StopBits = ONESTOPBIT; break;
    }

    // Software (XON/XOFF) flow control.
    dcb.fOutX = Outx_XonXoffFlow ? TRUE : FALSE;
    dcb.fInX  = Inx_XonXoffFlow  ? TRUE : FALSE;
    dcb.fBinary = TRUE;
    //AI(W906-TORQUE-COMM) 20260925: SPComm 預設＝golden rs232.dfm:43-52（Outx_CtsFlow/Outx_DsrFlow=False、DtrControl=DtrEnable、
    //  RtsControl=RtsEnable）；原本沿用驅動器殘留的 DCB（殘留硬體流控 ⇒ 寫不出去）
    dcb.fOutxCtsFlow      = FALSE;
    dcb.fOutxDsrFlow      = FALSE;
    dcb.fDtrControl       = DTR_CONTROL_ENABLE;
    dcb.fRtsControl       = RTS_CONTROL_ENABLE;
    dcb.fDsrSensitivity   = FALSE;
    dcb.fTXContinueOnXoff = TRUE;

    ::SetCommState(pImpl_->hFile, &dcb);

    COMMTIMEOUTS to;
    ::memset(&to, 0, sizeof(to));
    // ReadIntervalTimeout drives a per-char interval; the rest left at 0 so a
    // blocking ReadFile returns as soon as any byte (or the interval gap)
    // arrives -- the behavior the reader thread expects.
    to.ReadIntervalTimeout         = ReadIntervalTimeout ? ReadIntervalTimeout
                                                         : MAXDWORD;
    to.ReadTotalTimeoutMultiplier  = 0;
    to.ReadTotalTimeoutConstant    = ReadIntervalTimeout ? 50 : 0;   //AI(W906-TORQUE-COMM) 20260925: 有設 interval 時閒置也要回來（見檔頭 (3)）
    to.WriteTotalTimeoutMultiplier = 0;
    to.WriteTotalTimeoutConstant   = 2000;   //AI(W906-TORQUE-COMM) 20260925: 寫入執行緒最多卡 2 s（見檔頭 (1)，唯一刻意偏離 SPComm）
    ::SetCommTimeouts(pImpl_->hFile, &to);
#endif
}

// ===========================================================================
//  vclcompat/Comm.h
//  Portable shim for the SPComm VCL serial component (Spcomm::TComm).
//
//  Translator: AI(W?) 20260626
//
//  PROVENANCE (verified against golden ref):
//    * Component class: D:/HT9045/elec/Component/spcomm.hpp:154-277
//        class TComm : public Classes::TComponent  (the SPComm package, NOT a
//        custom rs232 class).  rs232.h:6 does #include "SPComm.hpp"; the data
//        module TCOM2 (rs232.h:11) hosts the IDE/.dfm-managed TComm instances
//        (Comm1-4, TempComm6, cmATC1-4, PadComm, cmVisionLight) plus a runtime
//        array TComm *CommSD[4] (rs232.h:119).
//    * 29 consumer .cpp files drive TComm via StartComm/StopComm/WriteCommData.
//
//  SCOPED API SURFACE (tallied via grep over all .cpp/.h; only what is used):
//      WriteCommData(char*, Word) -> bool   (116 calls; spcomm.hpp:242)
//      StopComm()                           ( 63 calls; spcomm.hpp:241)
//      StartComm()                          ( 37 calls; spcomm.hpp:240)
//      CommName   (AnsiString, 36 assigns;  spcomm.hpp:246, write=FCommName)
//      Parity     (TParity,    23 assigns;  spcomm.hpp:262, write=FParity)
//      ByteSize   (TByteSize,  20 assigns;  spcomm.hpp:261, write=SetByteSize)
//      StopBits   (TStopBits,  19 assigns;  spcomm.hpp:263, write=SetStopBits)
//      BaudRate   (unsigned,   18 assigns;  spcomm.hpp:247, write=SetBaudRate)
//      ParityCheck(bool,       12 assigns;  spcomm.hpp:248, write=SetParityCheck)
//      OnReceiveData (event,    3 runtime assigns; spcomm.hpp:272)
//      ReadIntervalTimeout / Outx_XonXoffFlow / Inx_XonXoffFlow (rare, plain)
//
//  Faithfully kept names so the 29 consumers translate UNCHANGED.  Since
//  vcl_compat.h neutralizes __property/__fastcall/__closure, the VCL property
//  syntax becomes plain public data members (CommName, BaudRate, ...) and the
//  setters' side effects (apply-to-open-port) are folded into StartComm/the
//  _ApplyCommState() helper -- consumers always set properties BEFORE
//  StartComm (verified: rs232.cpp/TCOM2::RS232Init, MyTempture.cpp, etc.), so
//  plain fields preserve behavior.
//
//  NOT implemented (do NOT add; never used on TComm in 906):
//      Handle, SendDataEmpty, GetModemState, OnReceiveError, OnRequestHangup,
//      OnModemStateChange, OnSendDataEmpty, Read/WriteTotalTimeout*,
//      Dtr/RtsControl, Xon/Xoff*, ReplacedChar, etc.  (Connected is NOT a TComm
//      member at all -- grep hits are TClientSocket->Socket->Connected.)
//
//  BACKING: Win32 \\.\COMx (CreateFileA/SetCommState/SetCommTimeouts/ReadFile/
//  WriteFile + a reader thread that posts received bytes to the OnReceiveData
//  closure).  SIM/offline mode (default when the port cannot be opened, or
//  forced via SetSimMode(true)) needs no hardware: WriteCommData buffers into
//  an internal tx capture, and a test hook SimInjectReceive(...) fires
//  OnReceiveData -- so the shim compiles/links/runs with zero hardware.
//
//  Lifecycle: 906 never does `new TComm` at runtime (grep clean); instances are
//  IDE/.dfm members constructed via the VCL component ctor TComm(TComponent*).
//  This shim therefore derives from vclcompat::TComponent and provides a
//  virtual ctor taking an owner so .dfm-equivalent member declarations compile.
//
//  Include via the vcl_compat.h umbrella (added there).
// ===========================================================================
#ifndef VCLCOMPAT_COMM_H
#define VCLCOMPAT_COMM_H

#include "vclcompat/AnsiString.h"
#include "vclcompat/TStringList.h"   // vclcompat::TObject
#include <string>
#include <vector>
#include <functional>

namespace vclcompat {

// BCB6 SysUtils Word (unsigned short).  Defined in TDateTime.h too; guard to
// avoid a duplicate typedef when both headers are visible in one TU.
#ifndef VCLCOMPAT_WORD_DEFINED
#define VCLCOMPAT_WORD_DEFINED
typedef unsigned short Word;
#endif

// ---------------------------------------------------------------------------
//  TComponent -- minimal VCL Classes::TComponent stand-in.
//
//  The real SPComm TComm derives from Classes::TComponent and is constructed by
//  the IDE with an owner.  We only need a base that (a) is virtual-dtor safe and
//  (b) accepts an owner pointer in its ctor, so .dfm-equivalent declarations and
//  the runtime `TComm *CommSD[4]` array translate without edits.  Derives from
//  the existing vclcompat::TObject (TStringList.h) for a common root.
// ---------------------------------------------------------------------------
class TComponent : public TObject {
public:
    explicit TComponent(TComponent* AOwner) : Owner_(AOwner) {}
    virtual ~TComponent() {}

    TComponent* Owner() const { return Owner_; }

private:
    TComponent* Owner_;
};

} // namespace vclcompat

// ---------------------------------------------------------------------------
//  namespace Spcomm -- faithful to the original SPComm.hpp namespace so the
//  consumers' `using namespace Spcomm;` (and unqualified TComm/TParity/...) keep
//  working after translation.
// ---------------------------------------------------------------------------
namespace Spcomm {

using vclcompat::AnsiString;
using vclcompat::TObject;
using vclcompat::TComponent;
using vclcompat::Word;

// Enums byte-identical to spcomm.hpp:30-39 (same order => same integer values).
enum TParity   { None, Odd, Even, Mark, Space };   // spcomm.hpp:30
enum TStopBits { _1, _1_5, _2 };                   // spcomm.hpp:34
enum TByteSize { _5, _6, _7, _8 };                 // spcomm.hpp:38

// Receive-data event (spcomm.hpp:88).  In BCB6 this is a __closure method
// pointer; vcl_compat.h neutralizes __closure, so we model the closure with
// std::function<> (assignable from a bound member/handler in translated code).
// Consumer handler signature (rs232.h): void(TObject* Sender, void* Buffer,
// Word BufferLength)  -- consumers spell the 2nd/3rd params `Pointer Buffer,
// WORD BufferLength`, which are the same types.
typedef std::function<void(TObject* Sender, void* Buffer, Word BufferLength)>
        TReceiveDataEvent;

// ---------------------------------------------------------------------------
//  TComm
// ---------------------------------------------------------------------------
class TComm : public TComponent {
public:
    // VCL virtual component ctor (spcomm.hpp:238).  Owner may be 0.
    explicit TComm(TComponent* AOwner);
    virtual ~TComm();

    // ---- public methods (spcomm.hpp:240-242) ------------------------------
    void StartComm();                                  // open the port
    void StopComm();                                   // close the port
    // Faithful sig (spcomm.hpp:242): bool WriteCommData(char*, Word).
    bool WriteCommData(char* pDataToWrite, Word dwSizeofDataToWrite);

    // ---- properties surfaced as plain members (see header note) -----------
    // Set BEFORE StartComm by every consumer; StartComm applies them.
    AnsiString CommName;            // spcomm.hpp:246  ("\\\\.\\COMx")
    unsigned   BaudRate;            // spcomm.hpp:247
    bool       ParityCheck;         // spcomm.hpp:248
    bool       Outx_XonXoffFlow;    // spcomm.hpp:254
    bool       Inx_XonXoffFlow;     // spcomm.hpp:255
    TByteSize  ByteSize;            // spcomm.hpp:261
    TParity    Parity;              // spcomm.hpp:262
    TStopBits  StopBits;            // spcomm.hpp:263
    unsigned   ReadIntervalTimeout; // spcomm.hpp:267

    // ---- event ------------------------------------------------------------
    TReceiveDataEvent OnReceiveData;  // spcomm.hpp:272

    // -----------------------------------------------------------------------
    //  SIM / test surface (NOT part of the BCB6 API; additive).
    // -----------------------------------------------------------------------
    // Force simulation mode regardless of CommName.  When sim is active,
    // StartComm succeeds without touching hardware, WriteCommData buffers into
    // the tx capture, and SimInjectReceive() drives OnReceiveData.
    void SetSimMode(bool bSim);
    bool IsSimMode() const;

    // True between a successful StartComm and the next StopComm.
    bool IsOpen() const;

    // Inspect the bytes WriteCommData captured in sim mode.
    const std::vector<char>& SimTxBuffer() const;
    void                     SimClearTx();

    // Push RX bytes as if they arrived on the wire; fires OnReceiveData with
    // (this, copy-of-buffer, len) exactly like the real reader thread.  No-op
    // if OnReceiveData is unset.
    void SimInjectReceive(const void* pData, Word len);

private:
    // Non-copyable (owns an OS handle / reader thread when on real hardware).
    TComm(const TComm&);
    TComm& operator=(const TComm&);

    // Apply CommName/BaudRate/Parity/ByteSize/StopBits/timeouts to the open
    // handle (real mode only).  Mirrors SPComm's _SetCommState/_SetCommTimeout.
    void ApplyCommState_();

    struct Impl;   // hides the Win32 handle + reader-thread state from headers
    Impl* pImpl_;  // owned; RAII-released in the dtor / StopComm

    // Real-mode reader-thread entry (Win32 LPTHREAD_START_ROUTINE-compatible).
    // Declared here (not a free function) so it can touch the private Impl.
    // void* in the signature avoids leaking <windows.h> types into the header.
    static unsigned long __stdcall ReaderProc_(void* param);
    //AI(W906-TORQUE-COMM) 20260925: 寫入執行緒（SPComm 的 TWriteThread）；同上理由宣告成 private static
    static unsigned long __stdcall WriterProc_(void* param);
};

} // namespace Spcomm

// Bring the SPComm names into global scope, matching the original header's
// trailing `using namespace Spcomm;` (spcomm.hpp:295) so unqualified TComm /
// TParity / TByteSize / TStopBits / TReceiveDataEvent resolve in translated
// consumer code.  Suppressible via the same umbrella flag as the rest of the
// compat layer.
#ifndef VCLCOMPAT_NO_GLOBAL_USING
using namespace Spcomm;
#endif

#endif // VCLCOMPAT_COMM_H
